{
  "findings": [
    {
      "check_id": "CKV_GCP_117",
      "title": "Basic IAM role assigned at project level",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The project-level binding grants the basic Editor role, which provides broad permissions across many Google Cloud services. This violates least privilege and increases the impact of a compromised user account."
    }
  ],
  "patched_code": "variable "trading_platform_role" {
  description = "Least-privilege predefined or custom IAM role for trading platform users."
  type        = string

  validation {
    condition = !contains([
      "roles/owner",
      "roles/editor",
      "roles/viewer",
    ], var.trading_platform_role)
    error_message = "trading_platform_role must not be a basic Owner, Editor, or Viewer role."
  }
}

resource "google_project_iam_binding" "trading_platform_admin" {
  project = var.project_id
  role    = var.trading_platform_role
  members = [
    "user:trader@${var.organization_domain}",
    "user:admin@${var.organization_domain}",
  ]
}
",
  "fix_summary": "Replaced the project-level Editor role with a required, configurable least-privilege role and added validation preventing use of GCP basic roles."
}
